// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2022, "6-7", [{"author":"Л. Фёдорова","question":"Какое из слов не обозначает волосы?","choices":["усы","бакенбарды","борода","лысина","коса"],"key":"Г","review":["Волосы и их отсутствие","Усы, бакенбарды и борода — волосы на лице. Коса состоит из заплетённых волос на голове.","Лысиной называют участок головы без волос. Это значение выделяется в данной группе."]},{"author":"Е. Амосов","question":"Дворник под окном зевал,\nТихо голубь _____.\nВставьте вместо прочерка нужное слово.","choices":["ворковал","куковал","гоготал","завывал","толковал"],"key":"А","review":["Голос голубя","Глагол зависит от птицы: кукушка кукует, гуси гогочут, а голубь издаёт тихие переливчатые звуки.","Про такие звуки говорят «голубь ворковал». Это слово подходит и по смыслу, и по рифме к «зевал»."]},{"author":"И. Рубанов","question":"Кто нередко использует в работе зубило?","choices":["ветеринар","слесарь","зубной врач","менеджер по кадрам","полицейский"],"key":"Б","review":["Кто берёт зубило","Зубило — металлический инструмент с острым краем. По нему ударяют, чтобы разрубить металл или срубить выступ.","Такой инструмент нужен в слесарном деле. Название «зубило» связано с режущей кромкой, хотя инструмент не лечит зубы."]},{"author":"И. Иткин","question":"Приехав в Лондон, Вася на _____ английском спросил у полисмена, как пройти на Бейкер-стрит.","choices":["ломком","ломаном","ломовом","ломающемся","сломанном"],"key":"Б","review":["Говорить на английском","Васе трудно свободно говорить на иностранном языке. Для такой речи есть устойчивое сочетание.","Говорят «на ломаном английском». «Ломкий» относится к предмету, который легко сломать, а «сломанный» — к уже испорченному предмету."]},{"author":"О. Подлесская","question":"Вставьте пропущенное слово в этот анекдот:\nПокупатель: — Мне хотелось бы купить какую-нибудь книжку.\nПродавец: — Вам что-нибудь _____?\nПокупатель: — Это не имеет значения, я на машине!","choices":["новенькое","интересное","страшное","лёгкое","красивое"],"key":"Г","review":["О чём шутка","Покупатель спрашивает о книжке, а в ответе упоминает машину. Значит, пропущенное слово можно понять в связи с переноской тяжёлого предмета.","Продавец предлагает «что-нибудь лёгкое» для чтения. Покупатель понимает «лёгкое» по весу и отвечает, что машину вес не затруднит."]},{"author":"А. Остроумова","question":"Когда маленького Васю спросили, кем работают его родители, он ответил: «Моя мама — тракторист, а папа — карьерист». Кем на самом деле работает папа Васи?","choices":["бизнесменом","специалистом по работе с молодёжью","тренером по боксу","добытчиком песка","продавцом"],"key":"Г","review":["Где работает «карьерист»","Вася называет трактористом того, кто работает на тракторе. Он применяет тот же образец к слову «карьер».","В карьере добывают песок, гравий и другие материалы. Значит, отец Васи — добытчик песка; в обычном языке «карьерист» означает человека, занятого продвижением по службе."]},{"author":"Н. Лебедева","question":"В каком примере себе имеет не такое значение, как в остальных?","choices":["Злодеи построили <strong>себе</strong> шалаш и жили в нём.","Пастухи стояли <strong>себе</strong> кучкой и всё смотрели за реку.","Я накачал <strong>себе</strong> шины на велосипеде и катался весь день.","Вахмурка положил <strong>себе</strong> под голову пучок травы и уснул.","Он купил <strong>себе</strong> портфель и стал ходить с ним по городу"],"key":"Б","review":["Два употребления «себе»","В А, В, Г и Д можно задать вопрос «кому?» или «для кого?»: построили себе, накачал себе, положил себе, купил себе.","В «стояли себе кучкой» слово ничего не называет и передаёт спокойное течение действия. Здесь «себе» — частица."]},{"author":"С. Подлесский","question":"Каким не может быть человек?","choices":["порывистым","дождливым","хмурым","ветреным","тучным"],"key":"Б","review":["Прилагательное о человеке","«Порывистый» и «ветреный» могут описывать характер, «хмурый» — настроение, «тучный» — телосложение.","«Дождливый» обычно относится к погоде или времени, когда много дождей. Человека этим словом не описывают."]},{"author":"Н. Лебедева","question":"Какой пример устроен не совсем так, как остальные?","choices":["Может, тебе поспать?","Может, тебе поесть?","Может, тебе сесть?","Может, тебе позвонить?","Может, тебе отдохнуть?"],"key":"Г","review":["Кто выполняет действие","В предложениях «тебе поспать», «тебе поесть», «тебе сесть» и «тебе отдохнуть» действие предлагается самому собеседнику.","«Может, тебе позвонить?» можно понять как предложение «Может, мне тебе позвонить?». Тогда звонит говорящий, а «тебе» обозначает адресата. Такая возможность отличает Г."]},{"author":"Л. Фёдорова","question":"Какого слова не существует в литературном языке?","choices":["никчёмный","никудышный","никогдашний","ничейный","ничтожный"],"key":"В","review":["Слово из литературного языка","«Никчёмный», «никудышный», «ничейный» и «ничтожный» употребляются по-русски. У некоторых есть разговорная окраска.","Слово «никогдашний» можно придумать по аналогии с «вчерашний», но в литературном языке оно не закрепилось."]},{"author":"А. Сомин","question":"Большинство логотипов метрополитенов выглядят однотипно. Например, №1 — это логотип метро города Лилль (Франция), №2 — логотип метро города Ренн (Франция), а №3 — логотип метро города Форталеза (Бразилия). В каком городе находится метро, логотип которого изображён под №4?","choices":["в Афинах (Греция)","в Генуе (Италия)","в Филадельфии (США)","в Санто-Доминго (Доминиканская Республика)","в Малаге (Испания)"],"key":"Д","review":["Буквы в логотипах метро","У всех четырёх логотипов можно узнать букву M, связанную со словом «метро». При этом знак номер 4 похож на две M подряд.","Две M дают первые буквы названия «Metro Málaga». Из предложенных городов только Малага начинается на M."],"figure":{"condition":{"items":[{"src":"assets/medvezhonok/2022/6-7-11-logo-1.webp","alt":"Бордовая буква М с маленьким перевёрнутым треугольником вверху","caption":"№ 1"},{"src":"assets/medvezhonok/2022/6-7-11-logo-2.webp","alt":"Белая строчная буква m внутри синего овала","caption":"№ 2"},{"src":"assets/medvezhonok/2022/6-7-11-logo-3.webp","alt":"Знак из зелёных и синих линий напоминает букву М с кругом внизу","caption":"№ 3"},{"src":"assets/medvezhonok/2022/6-7-11-logo-4.webp","alt":"Красные наклонные линии образуют две примыкающие буквы М","caption":"№ 4"}],"alt":"Четыре логотипа метрополитенов под номерами с 1 по 4."}}},{"author":"А. Сомин","question":"Какое из этих словосочетаний почти не встречается в современном языке?","choices":["каштановая аллея","дубовая аллея","лиственничная аллея","яблочная аллея","берёзовая аллея"],"key":"Г","review":["Названия аллей","Каштановую, дубовую, лиственничную и берёзовую аллеи называют по деревьям, которые вдоль них растут.","Для яблонь используется прилагательное «яблоневый», поэтому обычно говорят «яблоневая аллея». «Яблочный» относится к плодам, например к соку."]},{"author":"Е. Бикмаев","question":"Раньше в слове серчать писалась ещё одна буква, которая теперь не пишется. Какая?","choices":["п","т","в","д","б"],"key":"Г","review":["Старинная буква в слове","«Серчать» означает сердиться. В слове «сердиться» перед суффиксом сохраняется Д, как в «сердце» и «сердечный».","Прежде писали «сердчать». Со временем Д перестали произносить и писать в этой форме."]},{"author":"Б. Иомдин","question":"В какой паре слова означают одно и то же?","choices":["образ — образец","правдолюб — правдолюбец","столб — столбец","кон — конец","марафон — марафонец"],"key":"Б","review":["Два названия человека","Различим похожие слова по значению. Например, «марафон» — состязание, а «марафонец» — его участник.","И «правдолюб», и «правдолюбец» называют человека, который ценит правду. Это два слова с одним значением."]},{"author":"О. Подлесская","question":"Ходить _____ . Как нельзя закончить фразу?","choices":["босиком","гуськом","ходуном","пешком","калачиком"],"key":"Д","review":["Что можно делать калачиком","Говорят «ходить босиком», «гуськом» и «пешком». В выражении «ходить ходуном» что-нибудь сильно трясётся.","«Калачиком» можно свернуться или лежать. В такой позе не ходят."]},{"author":"С. Дьяченко","question":"Какое слово в составе некоторых устойчивых сочетаний может иметь значение «самая главная, примечательная часть чего-нибудь»?","choices":["трость","гроздь","гвоздь","гость","кость"],"key":"В","review":["Главная часть события","О самой заметной части программы говорят устойчивым выражением. В нём название крепёжной детали употребляется переносно.","Это «гвоздь программы». Слово «гвоздь» здесь называет самое примечательное."]},{"author":"И. Рубанов","question":"Эскадра — _____, эскадрон — _____, эскадрилья — _____. Что надо вставить вместо прочерков?","choices":["на море, в воздухе, на суше","на море, на суше, в воздухе","в воздухе, на море, на суше","на суше, на море, в воздухе","в воздухе, на суше, на море"],"key":"Б","review":["Три подразделения","Эскадра объединяет корабли и действует на море. Эскадрон относится к войскам на суше.","Эскадрилья состоит из самолётов и действует в воздухе. Нужен порядок «на море, на суше, в воздухе»."]},{"author":"И. Рубанов","question":"С нею я дошёл до сада,\nИ прошла моя досада,\nИ теперь я весь _______,\nВспомнив тёмную аллею.\n Какое слово мы пропустили в шуточном четверостишии поэта Дмитрия Минаева?","choices":["алею","белею","краснею","немею","потею"],"key":"А","review":["Рифма о прогулке","Вспоминая прогулку, герой краснеет. Ищем глагол с таким значением, который созвучен слову «аллею».","«Алеть» значит становиться алым. В форме «алею» слово рифмуется с «аллею» и создаёт игру похожих звучаний."]},{"author":"И. Рубанов","question":"Когда кладут кирпичную печь, перед укладкой кирпич выдерживают в воде, пока не перестанут выделяться пузырьки воздуха. Печники говорят: Кирпич должен «_____». Какое необычное слово мы заменили прочерком?","choices":["отболтаться","отговориться","откричаться","отмолчаться","отшипеться"],"key":"Д","review":["Почему шипит кирпич","Пока кирпич лежит в воде, из него выходит воздух. Это заметно по пузырькам, иногда слышно шипение.","Окончание действия передаёт приставка от-. По образцу «отшуметь» или «отзвенеть» печники говорят «отшипеться»."]},{"author":"Л. Фёдорова","question":"Что вспоминают, говоря об отрицательных качествах, которые дети наследуют от родителей?","choices":["овец","ягоды","горошины","яблоки","орехи"],"key":"Г","review":["Пословица о наследстве","В пословице сходство детей с родителями сравнивают с плодом возле дерева, на котором он вырос.","«Яблоко от яблони недалеко падает». Поэтому в данном случае вспоминают яблоки."]},{"author":"О. Подлесская","question":"Действие какого глагола в современном языке может быть направлено и на пищу, и на человека?","choices":["выпекать","запекать","допекать","распекать","опекать"],"key":"В","review":["Глагол о пище и человеке","Пищу можно «допекать», то есть доводить до готовности выпеканием. Например, можно ещё несколько минут допекать пирог.","«Допекать человека» значит надоедать ему, изводить постоянными просьбами или упрёками. Оба значения есть у одного глагола."]},{"author":"Е. Муравенко","question":"В какой из пар слова состоят не только из одинаковых букв, но и из одинаковых звуков?","choices":["ракета — карета","ручка — круча","пила — липа","серп — перс","брег — герб"],"key":"Б","review":["Буквы и звуки","Совпадение букв ещё не гарантирует совпадения звуков. Например, К в «ракета» мягкая, а в «карета» мягкая Р.","В «ручка» и «круча» Р и К твёрдые, Ч мягкая, ударение падает на У. После перестановки сохраняется тот же набор звуков."]},{"author":"Л. Иткина","question":"Весёлка — это небольшая лопаточка для перемешивания теста. Своё название она получила ____________.","choices":["за удовольствие, которое работа с ней доставляет хозяйкам","за то, что использовалась преимущественно в деревенских домах","за свою лёгкость","за форму","за цвет"],"key":"Г","review":["Как выглядит весёлка","Лопаточка для теста по форме напоминает небольшое весло: у неё есть ручка и более широкая плоская часть.","Название «весёлка» связано с «весло». Здесь важна форма инструмента, а не удовольствие от работы."]},{"author":"Л. Фёдорова","question":"Какой из глаголов образован иначе, чем остальные?","choices":["добегаться","допрыгаться","доплясаться","докувыркаться","все глаголы образованы одинаково"],"key":"Г","review":["Как образованы глаголы","В «добегаться», «допрыгаться» и «доплясаться» формы получены от «бегать», «прыгать», «плясать» добавлением до- и -ся.","В «докувыркаться» производящий глагол уже имеет -ся: «кувыркаться». К нему добавилась только приставка до-."]},{"author":"Е. Дубосарская и И. Иткин","question":"У поэта Саши Чёрного есть стихотворение «Живая азбука», включающее в себя двустишия, каждая строка которых начинается на одну и ту же букву, например: Астра в садике цветёт ― Аист, вам пора в поход! Какого из следующих двустиший на самом деле нет в «Азбуке» Саши Чёрного?","choices":["Гусь шагает, как солдат.\nГруша зреет ― Гриша рад.","Дятел в дуб всё тук да тук…\nДуб скрипит: «Что там за стук?»","Кот боится наших пчёл.\nКнигу Коленька прочёл.","Ослик влез в чертополох.\nОбезьянки ищут блох.","Пчёлка трудится весь день,\nПетушку и клюнуть лень."],"key":"В","review":["Строки «Живой азбуки»","В настоящем двустишии на К говорится о крысе, которая мчится через мост, и коте, который бежит за ней.","Вариант В предлагает другие строки про кота и Коленьку. Одинаковые начальные буквы сохранены, но это двустишие в книге не напечатано."]},{"author":"Б. Иомдин","question":"В повести Астрид Линдгрен «Эмиль из Лённеберги» (перевод Лилианны Лунгиной) Альфред поёт такой куплет: «В городе Экше на Реннской долине шведскую польку пляшут шутя, и с <strong>хуторов</strong> на Хультсфредской равнине <strong>девицы</strong> в танцах <strong>кружат</strong> до утра». С какими ударениями тут произносятся выделенные слова?","choices":["ху́торов, де́вицы, кру́жат","ху́торов, де́вицы, кружа́т","ху́торов, деви́цы, кру́жат","хуторо́в, деви́цы, кру́жат","хуторо́в, де́вицы, кружа́т"],"key":"Д","review":["Ударения в куплете","В строке о Хультсфредской равнине ритм требует «хуторо́в»: ударение приходится на последний слог.","В последней строке ударными становятся первый слог в «де́вицы» и последний слог в «кружа́т». Вместе эти формы даны в Д."]},{"author":"И. Чернов","question":"Маленькая Аня заявляет, что мама не разрешает ей есть мокрые _____.","choices":["чипсы","бутерброды","яйца","конфеты","кексы"],"key":"В","review":["Что Аня назвала мокрым","Ребёнок связывает «сырой» с влагой. Он может назвать мокрым то, что ещё не сварили.","Яйца нередко запрещают есть сырыми. Аня передала запрет необычными словами «мокрые яйца»."]},{"author":"Б. Иомдин","question":"На табло железнодорожных станций Ochodnica (Оходница) и Sološnica (Солошница) в Словакии Боря увидел надписи: odchod, cieľová stanica, koľaj, mešká. А вот какую информацию о поездах они передают (в перепутанном порядке): 1 — куда едет, 2 — какой путь, 3 — во сколько отправляется, 4 — на сколько опаздывает. Какой порядок цифр соответствует порядку надписей?","choices":["3, 1, 2, 4","1, 3, 2, 4","2, 1, 4, 3","4, 1, 2, 3","3, 1, 4, 2"],"key":"А","review":["Слова на табло","Словацкое <em>odchod</em> напоминает «отход» и обозначает отправление. <em>Cieľová stanica</em> — целевая станция, куда идёт поезд.","<em>Koľaj</em> связано с колеёй, то есть путём, а <em>mešká</em> сообщает об опоздании. Порядок по условию — 3, 1, 2, 4."]},{"author":"И. Иткин и Д. Колпакова","question":"Даны словосочетания, записанные по правилам дореволюционной (до реформы 1918 г.) орфографии: красивые глаза, быстрые ручьи, новыя перья, умныя собаки, суровыя горы. Как по правилам дореволюционной орфографии могут выглядеть словосочетания умные слоны, длинные уши, новые банки?","choices":["умныя слоны, длинныя уши, новыя банки","умные слоны, длинныя уши, новыя банки","умные слоны, длинные уши и длинныя уши, новые банки","умные слоны, длинныя уши, новые банки и новыя банки","умныя слоны, длинные уши и длинныя уши, новые банки и новыя банки"],"key":"Г","review":["Окончания до реформы","В примерах у существительных мужского рода прилагательные имеют -ие или -ые, а у женского и среднего — -ия или -ыя.","Слон мужского рода, ухо среднего. «Банки» могут быть от «банк» мужского рода или «банка» женского. Получаем «умные слоны», «длинныя уши», а дальше «новые банки» или «новыя банки»."]},{"author":"Б. Иомдин","question":"Есть редкий спортивный термин клэб — ‘клюшка для гольфа’. А со сколькими разными гласными буквами, помимо э, в русском языке есть слова из четырёх букв, начинающиеся на кл?","choices":["с пятью","с шестью","с семью","с восемью","с девятью"],"key":"Д","review":["Гласные в словах на «кл»","Соберём четырёхбуквенные слова с другими гласными после КЛ: клан, клей, клён, клин, клоп.","Продолжим «клуб», «клык», «ключ», «кляп». Получается девять букв: А, Е, Ё, И, О, У, Ы, Ю, Я."]}], {"year":2022,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"6-7-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2022-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
